use crate::{Action, Actor, Book, Focus, Genre, Register, RustForm, Signal, Story, StoryError};

pub fn apply(story: &mut Story) -> Result<(), StoryError> {
    joshua(story)?;
    judges(story)?;
    ruth(story)?;
    _1_samuel(story)?;
    _2_samuel(story)?;
    _1_kings(story)?;
    _2_kings(story)?;
    _1_chronicles(story)?;
    _2_chronicles(story)?;
    ezra(story)?;
    nehemiah(story)?;
    esther(story)?;
    Ok(())
}

